+/**
+ * Unit tests for SlackWebApiClient and loadWorkspaceNotificationConfig.
+ *
+ * Test matrix:
+ *
+ * SlackWebApiClient.postMessage:
+ *   1. Success — returns { ts, channel }
+ *   2. HTTP failure — throws with status code
+ *   3. ok: false — throws with Slack error
+ *   4. Missing ts field — throws
+ *
+ * createSlackWebApiClient:
+ *   5. Disabled (no botToken) — returns null
+ *   6. Disabled (no channelId) — returns null
+ *   7. Enabled — returns client instance
+ *
+ * SlackWebApiClient.updateMessage:
+ *   8. Success — resolves without throwing
+ *   9. HTTP failure — throws with status code
+ *  10. ok: false — throws with Slack error
+ *
+ * loadWorkspaceNotificationConfig:
+ *  11. Field present — returns config with channelId
+ *  12. Field absent (no notifications key) — returns null
+ *  13. Malformed yaml (unreadable file) — returns null
+ *  14. notifications present but slack absent — returns null
+ *  15. channel_id present but empty string — returns null
+ */
+
+import { describe, it, expect, vi, afterEach } from "vitest";
+import { mkdtempSync, writeFileSync, mkdirSync } from "node:fs";
+import { tmpdir } from "node:os";
+import { join } from "node:path";
+import {
+  SlackWebApiClient,
+  createSlackWebApiClient,
+} from "../src/slack/slack-web-api-client.js";
+import { loadWorkspaceNotificationConfig } from "../src/config/workspace-config.js";
+
+const BOT_TOKEN = "xoxb-test-token";
+const CHANNEL_ID = "C0123456789";
+
+afterEach(() => {
+  vi.unstubAllGlobals();
+});
+
+function makeClient(): SlackWebApiClient {
+  return new SlackWebApiClient({ botToken: BOT_TOKEN, channelId: CHANNEL_ID });
+}
+
+function mockFetchJson(body: unknown, ok = true, status = 200): ReturnType<typeof vi.fn> {
+  const fn = vi.fn().mockResolvedValue({
+    ok,
+    status,
+    text: async () => JSON.stringify(body),
+    json: async () => body,
+  });
+  vi.stubGlobal("fetch", fn);
+  return fn;
+}
+
+function mockFetchHttpError(status = 500): ReturnType<typeof vi.fn> {
+  const fn = vi.fn().mockResolvedValue({
+    ok: false,
+    status,
+    text: async () => "Internal Server Error",
+    json: async () => { throw new Error("not JSON"); },
+  });
+  vi.stubGlobal("fetch", fn);
+  return fn;
+}
+
+// ── postMessage ───────────────────────────────────────────────────────────────
+
+describe("SlackWebApiClient.postMessage", () => {
+  it("1. returns ts and channel on success", async () => {
+    mockFetchJson({ ok: true, ts: "1234567890.123456", channel: CHANNEL_ID });
+    const client = makeClient();
+    const result = await client.postMessage("Hello");
+    expect(result.ts).toBe("1234567890.123456");
+    expect(result.channel).toBe(CHANNEL_ID);
+  });
+
+  it("sends bearer auth header and correct channel", async () => {
+    const fn = mockFetchJson({ ok: true, ts: "9999.0001", channel: CHANNEL_ID });
+    const client = makeClient();
+    await client.postMessage("Hello");
+    const [url, init] = fn.mock.calls[0] as [string, RequestInit];
+    expect(url).toContain("chat.postMessage");
+    const headers = init.headers as Record<string, string>;
+    expect(headers["Authorization"]).toBe(`Bearer ${BOT_TOKEN}`);
+    const body = JSON.parse(init.body as string) as Record<string, unknown>;
+    expect(body["channel"]).toBe(CHANNEL_ID);
+    expect(body["text"]).toBe("Hello");
+  });
+
+  it("sends thread_ts when provided", async () => {
+    const fn = mockFetchJson({ ok: true, ts: "9999.0002", channel: CHANNEL_ID });
+    const client = makeClient();
+    await client.postMessage("Reply", { threadTs: "111.222" });
+    const [, init] = fn.mock.calls[0] as [string, RequestInit];
+    const body = JSON.parse(init.body as string) as Record<string, unknown>;
+    expect(body["thread_ts"]).toBe("111.222");
+  });
+
+  it("2. throws on HTTP failure", async () => {
+    mockFetchHttpError(503);
+    const client = makeClient();
+    await expect(client.postMessage("Hi")).rejects.toThrow("503");
+  });
+
+  it("3. throws when ok is false", async () => {
+    mockFetchJson({ ok: false, error: "channel_not_found" });
+    const client = makeClient();
+    await expect(client.postMessage("Hi")).rejects.toThrow("channel_not_found");
+  });
+
+  it("4. throws when ts is missing from response", async () => {
+    mockFetchJson({ ok: true, channel: CHANNEL_ID });
+    const client = makeClient();
+    await expect(client.postMessage("Hi")).rejects.toThrow("missing ts");
+  });
+});
+
+// ── createSlackWebApiClient ───────────────────────────────────────────────────
+
+describe("createSlackWebApiClient", () => {
+  it("5. returns null when botToken is undefined", () => {
+    expect(createSlackWebApiClient(undefined, CHANNEL_ID)).toBeNull();
+  });
+
+  it("6. returns null when channelId is undefined", () => {
+    expect(createSlackWebApiClient(BOT_TOKEN, undefined)).toBeNull();
+  });
+
+  it("7. returns a SlackWebApiClient when both are provided", () => {
+    const client = createSlackWebApiClient(BOT_TOKEN, CHANNEL_ID);
+    expect(client).toBeInstanceOf(SlackWebApiClient);
+  });
+
+  it("returns null when botToken is empty string", () => {
+    expect(createSlackWebApiClient("", CHANNEL_ID)).toBeNull();
+  });
+
+  it("returns null when channelId is empty string", () => {
+    expect(createSlackWebApiClient(BOT_TOKEN, "")).toBeNull();
+  });
+});
+
+// ── updateMessage ─────────────────────────────────────────────────────────────
+
+describe("SlackWebApiClient.updateMessage", () => {
+  it("8. resolves without throwing on success", async () => {
+    mockFetchJson({ ok: true, ts: "1234567890.123456", channel: CHANNEL_ID });
+    const client = makeClient();
+    await expect(client.updateMessage("1234567890.123456", "Updated text")).resolves.not.toThrow();
+  });
+
+  it("sends bearer auth header, channel, ts, and text", async () => {
+    const fn = mockFetchJson({ ok: true, ts: "1234567890.123456", channel: CHANNEL_ID });
+    const client = makeClient();
+    await client.updateMessage("1234567890.123456", "Updated text");
+    const [url, init] = fn.mock.calls[0] as [string, RequestInit];
+    expect(url).toContain("chat.update");
+    const headers = init.headers as Record<string, string>;
+    expect(headers["Authorization"]).toBe(`Bearer ${BOT_TOKEN}`);
+    const body = JSON.parse(init.body as string) as Record<string, unknown>;
+    expect(body["channel"]).toBe(CHANNEL_ID);
+    expect(body["ts"]).toBe("1234567890.123456");
+    expect(body["text"]).toBe("Updated text");
+  });
+
+  it("9. throws on HTTP failure", async () => {
+    mockFetchHttpError(500);
+    const client = makeClient();
+    await expect(client.updateMessage("1234567890.123456", "Hi")).rejects.toThrow("500");
+  });
+
+  it("10. throws when ok is false", async () => {
+    mockFetchJson({ ok: false, error: "message_not_found" });
+    const client = makeClient();
+    await expect(client.updateMessage("1234567890.123456", "Hi")).rejects.toThrow("message_not_found");
+  });
+});
+
+// ── loadWorkspaceNotificationConfig ──────────────────────────────────────────
+
+function makeTempWorkspace(yamlContent: string): string {
+  const dir = mkdtempSync(join(tmpdir(), "workspace-config-test-"));
+  writeFileSync(join(dir, "workspace.yaml"), yamlContent, "utf8");
+  return dir;
+}
+
+describe("loadWorkspaceNotificationConfig", () => {
+  it("11. returns config with channelId when field is present", () => {
+    const dir = makeTempWorkspace(`
+repos: []
+notifications:
+  slack:
+    channel_id: C0123456789
+`);
+    const config = loadWorkspaceNotificationConfig(dir);
+    expect(config).not.toBeNull();
+    expect(config?.slack.channelId).toBe("C0123456789");
+  });
+
+  it("12. returns null when notifications key is absent", () => {
+    const dir = makeTempWorkspace(`
+repos: []
+management_repo: mgmt
+`);
+    expect(loadWorkspaceNotificationConfig(dir)).toBeNull();
+  });
+
+  it("13. returns null when workspace.yaml does not exist (unreadable)", () => {
+    const dir = mkdtempSync(join(tmpdir(), "workspace-nofile-"));
+    expect(loadWorkspaceNotificationConfig(dir)).toBeNull();
+  });
+
+  it("14. returns null when notifications.slack is absent", () => {
+    const dir = makeTempWorkspace(`
+repos: []
+notifications:
+  email:
+    address: test@example.com
+`);
+    expect(loadWorkspaceNotificationConfig(dir)).toBeNull();
+  });
+
+  it("15. returns null when channel_id is empty string", () => {
+    const dir = makeTempWorkspace(`
+repos: []
+notifications:
+  slack:
+    channel_id: ""
+`);
+    expect(loadWorkspaceNotificationConfig(dir)).toBeNull();
+  });
+
+  it("returns null when notifications.slack exists but channel_id is absent", () => {
+    const dir = makeTempWorkspace(`
+repos: []
+notifications:
+  slack:
+    other_key: value
+`);
+    expect(loadWorkspaceNotificationConfig(dir)).toBeNull();
+  });
+});

