+  it("sends bearer auth header, channel, ts, and text", async () => {
+    const fn = mockFetchJson({ ok: true, ts: "1234567890.123456", channel: CHANNEL_ID });
+    const client = makeClient();
+    await client.updateMessage("1234567890.123456", "Updated text");
+    const [url, init] = fn.mock.calls[0] as [string, RequestInit];
