+  });
+
+  it("13. returns null when workspace.yaml does not exist (unreadable)", () => {
+    const dir = mkdtempSync(join(tmpdir(), "workspace-nofile-"));
+    expect(loadWorkspaceNotificationConfig(dir)).toBeNull();
+  });
+
+  it("14. returns null when notifications.slack is absent", () => {
+    const dir = makeTempWorkspace(`
+repos: []
+notifications:
+  email:
+    address: test@example.com
+`);
+    expect(loadWorkspaceNotificationConfig(dir)).toBeNull();
+  });
+
+  it("15. returns null when channel_id is empty string", () => {
+    const dir = makeTempWorkspace(`
+repos: []
+notifications:
+  slack:
+    channel_id: ""
+`);
+    expect(loadWorkspaceNotificationConfig(dir)).toBeNull();
+  });
+
+  it("returns null when notifications.slack exists but channel_id is absent", () => {
+    const dir = makeTempWorkspace(`
+repos: []
+notifications:
+  slack:
+    other_key: value
+`);
+    expect(loadWorkspaceNotificationConfig(dir)).toBeNull();
+  });
+});

